export const RULES={radius:25,duration:30,capture:0.4,bullMax:8,runnerMax:3,omegaMax:1,dt:0.01,decision:0.1};
export const INPUT=14,HIDDEN=16,OUTPUT=3,COUNT=HIDDEN*(INPUT+1)+OUTPUT*(HIDDEN+1);
// Both policies receive the same current separation, explicitly at input #13.
export const DISTANCE_INPUT_INDEX=12;
export const separation=s=>Math.hypot(s.m.x-s.b.x,s.m.y-s.b.y);
export const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
export const wrap=a=>Math.atan2(Math.sin(a),Math.cos(a));
export function rng(seed){let a=seed>>>0;return()=>{a+=0x6D2B79F5;let t=a;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return((t^t>>>14)>>>0)/4294967296;};}
export function normal(r){return Math.sqrt(-2*Math.log(Math.max(1e-12,r())))*Math.cos(2*Math.PI*r());}
export function network(weights,obs,cache){const hidden=cache||new Float64Array(HIDDEN);let k=0;for(let i=0;i<HIDDEN;i++){let z=weights[k++];for(let j=0;j<INPUT;j++)z+=weights[k++]*obs[j];hidden[i]=Math.tanh(z);}const out=[];for(let i=0;i<OUTPUT;i++){let z=weights[k++];for(let j=0;j<HIDDEN;j++)z+=weights[k++]*hidden[j];out.push(Math.tanh(z));}return out;}
export function observation(s){const b=s.b,m=s.m;return[b.x/25,b.y/25,m.x/25,m.y/25,b.v/8,m.v/3,Math.cos(b.h),Math.sin(b.h),Math.cos(m.h),Math.sin(m.h),(m.x-b.x)/50,(m.y-b.y)/50,separation(s)/50,s.t/30];}
export function initial(seed){const r=rng(seed);const point=()=>{const a=r()*Math.PI*2,d=Math.sqrt(r())*20;return{x:Math.cos(a)*d,y:Math.sin(a)*d,h:r()*Math.PI*2,v:0};};const b=point();let m;do{m=point();}while(Math.hypot(m.x-b.x,m.y-b.y)<8);b.h=Math.atan2(m.y-b.y,m.x-b.x)+(r()-.5)*Math.PI;return{b,m,t:0,min:Math.hypot(m.x-b.x,m.y-b.y),caught:false,done:false,wallB:0,wallM:0};}
// Optional imitation initialization is a real supervised weight update, not an inference fallback.
export function makePolicy(seed,role,warm=true){const r=rng(seed),w=Array.from({length:COUNT},()=>normal(r)*.18);if(!warm)return w;const hidden=new Float64Array(HIDDEN);for(let iter=0;iter<10000;iter++){const s=initial((r()*4294967296)>>>0);s.b.v=r()*8;s.m.v=r()*3;s.t=r()*30;const obs=observation(s),b=s.b,m=s.m;let dx=m.x-b.x,dy=m.y-b.y,v=role==='bull'?7.8:2.98;if(role==='runner'){const d=Math.hypot(dx,dy);dx/=d;dy/=d;const radial=Math.hypot(m.x,m.y),edge=clamp((radial-12)/10,0,1)*2;dx-=m.x/Math.max(1,radial)*edge;dy-=m.y/Math.max(1,radial)*edge;}const h=Math.atan2(dy,dx),target=[2*v/(role==='bull'?8:3)-1,Math.cos(h)*.95,Math.sin(h)*.95],out=network(w,obs,hidden),delta=out.map((y,i)=>(y-target[i])*(1-y*y)),dh=new Float64Array(HIDDEN);let k=HIDDEN*(INPUT+1);for(let i=0;i<OUTPUT;i++){w[k++]-=.018*delta[i];for(let j=0;j<HIDDEN;j++){dh[j]+=delta[i]*w[k];w[k++] -=.018*delta[i]*hidden[j];}}k=0;for(let j=0;j<HIDDEN;j++){const d=dh[j]*(1-hidden[j]*hidden[j]);w[k++]-=.018*d;for(let i=0;i<INPUT;i++)w[k++] -=.018*d*obs[i];}}return w;}
export function actions(s,bw,mw,config,locked){const obs=observation(s),mo=network(mw,obs),bo=config.mode==='neural'?network(bw,obs):null;return{bv:bo?(bo[0]+1)*4:config.fixedSpeed,bh:bo?Math.atan2(bo[2],bo[1]):config.mode==='straight'?locked:Math.atan2(s.m.y-s.b.y,s.m.x-s.b.x),mv:(mo[0]+1)*1.5,mh:Math.atan2(mo[2],mo[1])};}
// A wall cancels the outward displacement; it never reflects heading. At rest the
// unspecified zero-speed rule is bounded to 1 rad/s, the moving limit as v -> 0.
function wallMove(p,x,y){if(Math.hypot(x,y)<=25)return{x,y,wall:false};const dx=x-p.x,dy=y-p.y,A=dx*dx+dy*dy;if(A<1e-20)return{x:p.x,y:p.y,wall:true};const B=2*(p.x*dx+p.y*dy),C=p.x*p.x+p.y*p.y-625;const u=clamp((-B+Math.sqrt(Math.max(0,B*B-4*A*C)))/(2*A),0,1);return{x:p.x+dx*u,y:p.y+dy*u,wall:true};}
export function contactFraction(b0,m0,b1,m1,r=.4){const x=m0.x-b0.x,y=m0.y-b0.y,dx=(m1.x-m0.x)-(b1.x-b0.x),dy=(m1.y-m0.y)-(b1.y-b0.y),A=dx*dx+dy*dy,C=x*x+y*y-r*r;if(C<0)return 0;if(A<1e-20)return null;const B=2*(x*dx+y*dy),D=B*B-4*A*C;if(D<=0)return null;const u=(-B-Math.sqrt(D))/(2*A),end=(-B+Math.sqrt(D))/(2*A);return u<1&&end>0?Math.max(0,u):null;}
export function step(s,a,dt=RULES.dt){if(s.done)return s;dt=Math.min(dt,30-s.t);const b=s.b,m=s.m,bv=clamp(a.bv,0,8),mv=clamp(a.mv,0,3),turn=clamp(wrap(a.bh-b.h),-dt,dt),nh=b.h+turn;const omega=turn/dt;let bx,by;if(Math.abs(omega)>1e-10){bx=b.x+bv/omega*(Math.sin(nh)-Math.sin(b.h));by=b.y+bv/omega*(Math.cos(b.h)-Math.cos(nh));}else{bx=b.x+bv*dt*Math.cos(b.h);by=b.y+bv*dt*Math.sin(b.h);}const bn=wallMove(b,bx,by),mn=wallMove(m,m.x+mv*dt*Math.cos(a.mh),m.y+mv*dt*Math.sin(a.mh));const u=contactFraction(b,m,bn,mn);const frac=u===null?1:u;const dx=(mn.x-m.x)-(bn.x-b.x),dy=(mn.y-m.y)-(bn.y-b.y),rx=m.x-b.x,ry=m.y-b.y,closest=clamp(-(rx*dx+ry*dy)/(dx*dx+dy*dy||1),0,frac);s.min=Math.min(s.min,Math.hypot(rx+dx*closest,ry+dy*closest));s.b={x:b.x+(bn.x-b.x)*frac,y:b.y+(bn.y-b.y)*frac,h:b.h+turn*frac,v:bn.wall?Math.hypot(bn.x-b.x,bn.y-b.y)/dt:bv};s.m={x:m.x+(mn.x-m.x)*frac,y:m.y+(mn.y-m.y)*frac,h:a.mh,v:mn.wall?Math.hypot(mn.x-m.x,mn.y-m.y)/dt:mv};s.t+=dt*frac;s.wallB+=bn.wall?dt*frac:0;s.wallM+=mn.wall?dt*frac:0;s.caught=u!==null;s.done=s.caught||s.t>=30-1e-8;return s;}
export function score(s){const bull=s.caught?70+30*(1-s.t/30):30*(1-clamp(s.min/50,0,1));return{bull,runner:100-bull};}
export function simulate(bw,mw,config,seed,record=false){const s=initial(seed),frames=record?[structuredClone(s)]:null;const locked=Math.atan2(s.m.y-s.b.y,s.m.x-s.b.x);let i=0,a,proximity=0,near=0;while(!s.done){if(i%10===0){a=actions(s,bw,mw,config,locked);near=Math.exp(-Math.hypot(s.m.x-s.b.x,s.m.y-s.b.y)/5);}const before=s.t;step(s,a);proximity+=near*(s.t-before);i++;if(record&&(i%5===0||s.done))frames.push(structuredClone(s));}return{...score(s),caught:s.caught,time:s.t,min:s.min,wallB:s.wallB,wallM:s.wallM,proximity:proximity/Math.max(s.t,1e-9),frames};}

// Fitness is separate from the stable, backwards-compatible replay score.
export function fitness(e,role){return role==='bull'
  ?100*Number(e.caught)+25*(1-e.time/30)+10*e.proximity+5*Math.exp(-e.min/3)-3*e.wallB/30
  :100*Number(!e.caught)+25*e.time/30+5*(1-e.proximity)-3*e.wallM/30;}
